// Runtime fingerprint settings (app.json runtimeVersion.policy = "fingerprint").
//
// - Version numbers are left out: production builds auto-increment
//   android.versionCode / ios.buildNumber, and including them gave every store
//   build its own runtime, so OTA updates published from main never matched.
// - Setting sourceSkips replaces Expo's default, so the default
//   (PackageJsonAndroidAndIosScriptsIfNotContainRun) is kept explicitly:
//   prebuild rewrites the "android"/"ios" scripts on the EAS builder.
// - android/ and ios/ are generated by prebuild (CNG) and never committed;
//   ignoring them keeps the builder's fingerprint equal to the one computed
//   before upload.
// Real native changes (dependencies, config plugins, native config) still
// change the fingerprint.
/** @type {import('expo/fingerprint').Config} */
const { SourceSkips } = require('expo/fingerprint');

module.exports = {
  sourceSkips:
    SourceSkips.ExpoConfigVersions | SourceSkips.PackageJsonAndroidAndIosScriptsIfNotContainRun,
  ignorePaths: ['android/**/*', 'ios/**/*'],
};
